import React, { useState } from 'react';
import axios from 'axios';
import BookingForm from './BookingForm'; // Aapka purana component
import './App.css';

function App() {
  const [trackingId, setTrackingId] = useState('');
  const [parcel, setParcel] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [view, setView] = useState('book'); // 'book' ya 'track' switch karne ke liye

  const handleTrack = async () => {
    if (!trackingId) {
      setError("Please enter a tracking ID");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const cleanId = trackingId.trim().toUpperCase();
      const response = await axios.get(`http://localhost:9023/api/parcels/track/${cleanId}`);

      if (response.data) {
        setParcel(response.data);
      } else {
        setError('No data found for this ID');
        setParcel(null);
      }
    } catch (err) {
      console.error("Fetch Error:", err);
      setError('Parcel not found. Please check the ID (e.g., PRT-12345)');
      setParcel(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="App">
      <header className="app-header">
        <h1>Porter Logistics System</h1>

        <div className="nav-tabs">
          <button className={view === 'book' ? 'active' : ''} onClick={() => setView('book')}>Book a Vehicle</button>
          <button className={view === 'track' ? 'active' : ''} onClick={() => { setView('track'); setParcel(null); setError(null); }}>Track Order</button>
        </div>

        <hr />

        {view === 'book' && (
          <div className="booking-section">
            <BookingForm />
          </div>
        )}

        {view === 'track' && (
          <div className="tracking-section">
            <div className="search-box">
              <input
                type="text"
                placeholder="Enter tracking number (e.g. PRT-123)"
                value={trackingId}
                onChange={(e) => setTrackingId(e.target.value)}
              />
              <button onClick={handleTrack} disabled={loading}>
                {loading ? 'Searching...' : 'Track Now'}
              </button>
            </div>

            {error && <p className="error-message" style={{ color: 'red', marginTop: '10px' }}>{error}</p>}

            {parcel && (
              <div className="result-card">
                <h2>Order Details</h2>
                <div className="info-grid">
                  <p><strong>Tracking ID:</strong> {parcel.trackingId}</p>
                  <p><strong>Status:</strong> <span className="status-tag">{parcel.status}</span></p>
                  <p><strong>Vehicle:</strong> {parcel.vehicleType}</p>
                  <p><strong>Total Price:</strong> ₹{parcel.totalPrice}</p>
                  <hr />
                  <p><strong>From:</strong> {parcel.sourceAddress}</p>
                  <p><strong>To:</strong> {parcel.destinationAddress}</p>
                  <p><strong>Distance:</strong> {parcel.distanceKm} km</p>
                  <p><strong>Sender:</strong> {parcel.senderName} ({parcel.senderPhone})</p>
                </div>
              </div>
            )}
          </div>
        )}
      </header>
    </div>
  );
}

export default App;
